with with_latest as (select s.id, s.rating, x.price from suppliers s join lateral (select c.price from products c where c.supplier_id = s.id order by c.price desc, c.id desc limit 1) x on true) select case when price >= 970 then 'HIGH' else 'LOW' end as price_tier, case when rating >= 3.7 then 'PREMIUM' else 'STANDARD' end as rating_tier, count(distinct id) as distinct_ids, round(avg(price), 2) as avg_price, stddev_samp(rating) as rating_stddev, percentile_approx(rating, 0.5) as rating_p50, dense_rank() over (partition by case when price >= 970 then 'HIGH' else 'LOW' end order by round(avg(price), 2) desc) as avg_price_dense_rank from with_latest group by case when price >= 970 then 'HIGH' else 'LOW' end, case when rating >= 3.7 then 'PREMIUM' else 'STANDARD' end order by distinct_ids desc;
